document.addEventListener("DOMContentLoaded",()=>{console.log("🔍 DEBUG: Verificando funcionalidad de idioma...");const o=document.getElementById("languageSelect");console.log("Selector de idioma encontrado:",!!o),o?(console.log("Valor actual del selector:",o.value),console.log("Opciones disponibles:",Array.from(o.options).map(o=>o.value)),o.addEventListener("change",o=>{console.log("🔍 DEBUG: Cambio de idioma detectado:",o.target.value),document.cookie=`lang=${o.target.value}; path=/; max-age=31536000; SameSite=Lax`,console.log("🔍 DEBUG: Cookie establecida");const e=new URL(window.location.href);e.searchParams.set("lang",o.target.value),console.log("🔍 DEBUG: Nueva URL:",e.toString()),window.location.href=e.toString()}),console.log("✅ Listener de cambio agregado al selector")):console.log("❌ ERROR: No se encontró el selector de idioma"),console.log("🔍 DEBUG: Cookies actuales:",document.cookie);const e=new URLSearchParams(window.location.search);console.log("🔍 DEBUG: Parámetro lang en URL:",e.get("lang")),console.log("🔍 DEBUG: Verificación completada")});